'use client';
import {useState} from 'react'; import AppShell from '@/components/AppShell';
const days=Array.from({length:30},(_,i)=>i+1);
export default function Calendar(){const [selected,setSelected]=useState(15);return <AppShell><div className="pagehead"><div className="eyebrow">September 2026</div><h1>Calendar</h1><p className="muted">Consistency heatmap.</p></div><section className="card"><div className="weekdays">{['S','M','T','W','T','F','S'].map((x,i)=><span key={i}>{x}</span>)}</div><div className="calendargrid"><i/><i/>{days.map(d=><button key={d} onClick={()=>setSelected(d)} className={`${d<15?'good':''} ${d===selected?'selected':''}`}>{d}</button>)}</div></section><section className="section"><h2>{selected} September</h2><div className="card"><div className="between"><span className="muted">Daily score</span><b>{selected<15?'88%':'—'}</b></div><div className="between"><span className="muted">Workout</span><b>{selected<15?'Completed ✓':'Not logged'}</b></div><div className="between"><span className="muted">Weight</span><b>{selected<15?'75.8 kg':'—'}</b></div></div></section></AppShell>}
